{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "flip",
  "supportive_card_ids": ["C63", "C73", "C67", "C28", "C22", "C32"],
  "contradictory_card_ids": ["C07", "C13", "C16", "C42", "C06", "C30", "C37"],
  "prediction_basis_card_ids": ["C63", "C73", "C67", "C28", "C22"],
  "claims": [
    {
      "claim": "The query is a fully ionized aryloxyacetic acid at intestinal pH (logD -0.75), and L5 shows that a free carboxylic acid (ME3277) had poor absorptive flux unless its acids were esterified (C73), providing mechanistic evidence that the ionized acid form has low intestinal permeability.",
      "card_ids": ["C73"]
    },
    {
      "claim": "Pravastatin, an acidic drug with a similar ionization profile, undergoes BCRP-mediated efflux in Caco-2 cells (efflux ratio reduced to 2.1 only in the presence of the ABCG2 inhibitor Ko143, C63), indicating that acidic substrates can be subject to gut-wall efflux that limits net absorption.",
      "card_ids": ["C63"]
    },
    {
      "claim": "The closest aryloxyacetic acid fused-ring analog FK788 had low oral bioavailability in rats (9.6%, C28), and KNI-272 in a syrup formulation under fed conditions had F = 15.72% (C22), providing direct low outcomes that align with the mechanistic efflux/metabolism evidence.",
      "card_ids": ["C28", "C22"]
    },
    {
      "claim": "Direct high-F analogs (FK788 human 55%, C07; etodolac 0.80, C13; cicaprost ~100%, C42) are structurally distinct and do not establish that this specific rigid benzindene aryloxyacetic acid avoids efflux or first-pass loss.",
      "card_ids": ["C07", "C13", "C42"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "changed",
      "card_ids": ["C63", "C73", "C67", "C72"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "No treprostinil-specific record is present in the supplied cards; the low prediction relies on analog and mechanistic transfer.",
    "Fed-state effects on this specific molecule are not directly measured; food may alter absorption or first-pass unpredictably.",
    "The transporter status (BCRP, MCT, OATP) of the query is not directly assayed.",
    "The target species is not specified; human versus rat differences could change the outcome."
  ],
  "decision_summary": "Flipped to low because L5 provides coherent gut-wall efflux and poor free-acid permeability evidence (C63, C73) that, together with the query's full ionization and negative logD, affirmatively supports F < 20%; the high-F analogs are less transferable due to structural and species differences."
}

